set
  title = 'Philosophy of Religion',
  goal = 'Philosophy of Religion',
  summary = 'The syllabus covers classical themes and adds contemporary design, fine-tuning, hiddenness, religious epistemology, science, afterlife, ethics, politics, and global/comparative philosophy of religion.',
  data = $phrejson${"slug": "philosophy-of-religion", "title": "Philosophy of Religion", "description": "The syllabus covers classical themes and adds contemporary design, fine-tuning, hiddenness, religious epistemology, science, afterlife, ethics, politics, and global/comparative philosophy of religion.", "topics": [{"id": "afc18556-f0dc-4784-b20a-20ae4a0994a3", "type": "topic", "title": "What Is Philosophy of Religion?", "description": "Defines the field, its methods, its relation to theology and religious studies, and its place in contemporary philosophy.", "children": [{"id": "91b6f5d7-3aba-4785-bef9-f7a9af25d96d", "type": "subtopic", "title": "Field and scope", "children": [{"id": "15063457-ad7a-41ac-9141-61fe407e89c0", "type": "concept", "title": "Arguments, concepts, and assumptions"}, {"id": "1ee14957-e295-40f3-be4d-fb2d21f21837", "type": "concept", "title": "Theology, philosophy, and religious studies"}, {"id": "f3611483-f8e6-43ab-a142-26fe5e2474b0", "type": "concept", "title": "Analytic, continental, and comparative styles"}], "description": "Students learn what makes a question philosophical rather than merely historical, sociological, or devotional."}, {"id": "05529acc-6269-4be0-a08d-04ce74ff6c92", "type": "subtopic", "title": "Defining religion", "children": [{"id": "bd5caaf4-2a00-44e0-9648-2f8409a68351", "type": "concept", "title": "Family resemblance approaches"}, {"id": "5e1b73fc-08da-4b0e-9c8d-f2dcd33dee0c", "type": "concept", "title": "Belief, practice, community, and ultimacy"}, {"id": "f94de2e2-f0bb-41b0-a56c-7b27f539468d", "type": "concept", "title": "Problems with God-centered definitions"}], "description": "The course treats definitions as contested tools rather than neutral starting points."}, {"id": "dcf1886d-c52a-4a67-a65d-01f7210dd75a", "type": "subtopic", "title": "Philosophical method", "children": [{"id": "c50b86f6-12fa-402f-b05d-96dc423ae2e4", "type": "concept", "title": "Premises and conclusions"}, {"id": "f92685ce-2ade-4004-8bcf-50efbec55979", "type": "concept", "title": "Validity and soundness"}, {"id": "94c3b785-6eef-4bc0-baf1-71055b5e871b", "type": "concept", "title": "Objections and replies"}], "description": "Students practice charitable reconstruction before criticism."}]}, {"id": "56dd6997-2049-4cbc-99c6-ebeb74e2ef67", "type": "topic", "title": "Concepts of God, Ultimate Reality, and Religious Worldviews", "description": "Compares theism, non-theistic traditions, ultimate reality, naturalism, and secular alternatives.", "children": [{"id": "2f0d915f-27f9-4b8b-b2bd-25365ed7d419", "type": "subtopic", "title": "Classical theism", "children": [{"id": "a4857461-19bd-4d62-b3dd-2270afcd129f", "type": "concept", "title": "Creator and sustainer"}, {"id": "72fc16b3-a4b1-44c1-bfb1-64e0b9a7ae64", "type": "concept", "title": "Necessary being"}, {"id": "edd5fc5d-6afa-42cd-8e6a-4872fbdf8309", "type": "concept", "title": "Perfect goodness and personhood"}], "description": "Students identify the main claims of monotheistic philosophical theology."}, {"id": "de558e4b-55b2-47d6-80d8-177c324491b0", "type": "subtopic", "title": "Alternative ultimates", "children": [{"id": "629a1c50-54c3-4907-bf82-ec5447750aba", "type": "concept", "title": "Brahman, emptiness, Dao, and nirvana"}, {"id": "d2aecb27-0f58-4928-9bb6-da68830c225c", "type": "concept", "title": "Personal and impersonal ultimates"}, {"id": "530f3864-3357-430b-b0c2-dbb8d05e4bae", "type": "concept", "title": "Sacred reality and liberation"}], "description": "The topic broadens the course beyond one model of God."}, {"id": "5258e202-843d-47a6-ba5d-a657da17f012", "type": "subtopic", "title": "Worldview comparison", "children": [{"id": "a64e2993-62bc-4a4c-90c6-6539f85b27f6", "type": "concept", "title": "Naturalism"}, {"id": "e62006b5-0b84-4064-a0be-6b206ed93472", "type": "concept", "title": "Pantheism and panentheism"}, {"id": "59231e35-1896-4c8d-a259-9518e40708c4", "type": "concept", "title": "Nonrealist and symbolic approaches"}], "description": "Students learn to compare religious and secular pictures of reality fairly."}]}, {"id": "85b17622-664e-40d6-a117-0e39519644c5", "type": "topic", "title": "Classical Arguments for God: Cosmological, Ontological, and Teleological", "description": "Studies major arguments for theism and how philosophers evaluate their premises and conclusions.", "children": [{"id": "cfff819b-ad82-4576-a51a-4ca6cbe5def2", "type": "subtopic", "title": "Cosmological arguments", "children": [{"id": "9342bbb2-59f3-4daf-ad84-3b721c7da0e2", "type": "concept", "title": "First cause"}, {"id": "14c0261d-2b5a-477f-80e6-ee3459229990", "type": "concept", "title": "Contingency"}, {"id": "8ef8fdc7-bce8-4dff-9be0-9a9cf786c21b", "type": "concept", "title": "Kalam-style reasoning"}], "description": "Students ask whether contingency, causation, or existence points beyond the universe."}, {"id": "263df77d-2ff0-4e66-8415-eb0e2c08255d", "type": "subtopic", "title": "Ontological arguments", "children": [{"id": "52e047a7-9bbc-49f3-8159-640df6686ba0", "type": "concept", "title": "Anselm"}, {"id": "6b0eb4df-0c1c-486b-8bb4-26393ec4c579", "type": "concept", "title": "Modal versions"}, {"id": "93fc74af-fb0a-4694-8282-deff1aabb565", "type": "concept", "title": "Gaunilo and Kantian objections"}], "description": "Students study arguments that reason from the concept of God to existence."}, {"id": "c5f66c51-7bfa-4553-a272-cb3a7001eba7", "type": "subtopic", "title": "Teleological arguments", "children": [{"id": "bfd16733-7217-4123-8964-5df1c3dbe61a", "type": "concept", "title": "Classical design"}, {"id": "c49760b4-f050-4996-a549-dff2883179bd", "type": "concept", "title": "Hume's critiques"}, {"id": "3b53ab85-11a1-4db3-b54e-3797e354a8bd", "type": "concept", "title": "Inference to best explanation"}], "description": "Students examine order, purpose, and design reasoning."}]}, {"id": "549c2760-3fe6-4256-99ca-9a4f2d36708f", "type": "topic", "title": "Design, Fine-Tuning, Moral, and Pragmatic Arguments", "description": "Adds contemporary forms of theistic argument beyond the standard classical trio.", "children": [{"id": "09273f47-6659-458f-9bbe-8e6e096bd551", "type": "subtopic", "title": "Fine-tuning", "children": [{"id": "ff6aeb1b-f715-410c-85f7-05c9a4a6457d", "type": "concept", "title": "Constants and life-permitting universes"}, {"id": "fad9a750-be25-4f68-9f9a-1af02530c71f", "type": "concept", "title": "Multiverse replies"}, {"id": "a235ec34-dd9c-4752-ae43-a3bc49df2602", "type": "concept", "title": "Probability cautions"}], "description": "Students learn how contemporary cosmology enters philosophy of religion."}, {"id": "5fb2f92e-f323-4246-9634-933e4f68ba2a", "type": "subtopic", "title": "Moral arguments", "children": [{"id": "660701f5-1d13-436a-ab46-5c7c27aff5de", "type": "concept", "title": "Moral realism"}, {"id": "74ffd3ba-429b-40f2-a9bf-2b497d16d88d", "type": "concept", "title": "Divine command theory"}, {"id": "16037e28-7ba2-458e-94fb-7831c6a9f7d4", "type": "concept", "title": "Euthyphro problem"}], "description": "The topic asks whether moral normativity points to a religious foundation."}, {"id": "2f292f97-ee59-4365-a738-3b9d8de110eb", "type": "subtopic", "title": "Pragmatic arguments", "children": [{"id": "c6589eef-5ea1-4f84-bdc5-97e70b222b52", "type": "concept", "title": "Pascal's wager"}, {"id": "2e55c1b3-2764-4786-a234-5e04bb26e50c", "type": "concept", "title": "James's will to believe"}, {"id": "6aa7a8f2-7d51-4a7d-b69b-cf7420fb77a8", "type": "concept", "title": "Costs of belief and unbelief"}], "description": "Students evaluate belief through practical reason rather than only evidence."}]}, {"id": "4c3b03b9-1d08-46c8-9047-49021e42e5e0", "type": "topic", "title": "Divine Attributes and Coherence of Theism", "description": "Examines omnipotence, omniscience, eternity, simplicity, goodness, freedom, and personhood.", "children": [{"id": "34afad5a-01b3-434e-a748-b3bb40f8ec14", "type": "subtopic", "title": "Omni-attributes", "children": [{"id": "3ed257cb-5017-4c16-b4f2-18915c67bbab", "type": "concept", "title": "Omnipotence"}, {"id": "f8353c63-7a9d-45e4-9961-5a6d482b215f", "type": "concept", "title": "Omniscience and foreknowledge"}, {"id": "bbf2b4a2-275c-4d57-b472-294cdba2984d", "type": "concept", "title": "Omnibenevolence"}], "description": "Students analyze whether traditional divine attributes are coherent."}, {"id": "a7414570-0cdb-48fb-9332-91ab026ebe47", "type": "subtopic", "title": "Time and simplicity", "children": [{"id": "49e8b64f-e77e-4638-abfe-4159bd84ffb3", "type": "concept", "title": "Eternity and everlastingness"}, {"id": "fb638fe4-1c2b-496d-aa6a-d92e63ff59d5", "type": "concept", "title": "Immutability"}, {"id": "0eab76d5-00cd-49ab-8fb6-b04f99e27726", "type": "concept", "title": "Divine simplicity"}], "description": "The topic connects God to metaphysics of time and composition."}, {"id": "fd66ad66-d0a9-4e25-afc3-f8553ae200c8", "type": "subtopic", "title": "Freedom and providence", "children": [{"id": "83ec8f6f-bd8e-44d0-88e2-3dcdb698cfc2", "type": "concept", "title": "Providence"}, {"id": "b4f9a3fb-f569-4bd4-9456-7c8eb93eee2c", "type": "concept", "title": "Middle knowledge"}, {"id": "5c9ba4cf-287f-4706-9568-7edaf311b121", "type": "concept", "title": "Free will and determinism"}], "description": "Students test tensions between divine action and creaturely freedom."}]}, {"id": "9c1c665e-1c2e-4d11-8560-a1cc57e20a83", "type": "topic", "title": "Problem of Evil, Suffering, Horror, and Divine Hiddenness", "description": "Analyzes the strongest arguments against theism from evil, suffering, and apparent absence of God.", "children": [{"id": "b1e30b0b-e197-46d3-aa09-2cba4d56305d", "type": "subtopic", "title": "Logical and evidential evil", "children": [{"id": "3dbc623b-efed-47d7-b46a-1da6b016e30f", "type": "concept", "title": "Logical problem"}, {"id": "42ce6de2-d76f-4869-a1b8-2794422a0a00", "type": "concept", "title": "Evidential problem"}, {"id": "7bcacb2e-3593-4876-9770-5d1da94d4af4", "type": "concept", "title": "Theodicy and defense"}], "description": "Students distinguish incompatible claims from probability-based arguments."}, {"id": "9af71013-3afd-45f2-a379-2dd1904a53c3", "type": "subtopic", "title": "Kinds of suffering", "children": [{"id": "57013b9b-a6d9-4aab-ae99-a36f59686ea4", "type": "concept", "title": "Natural evil"}, {"id": "a329b72a-a653-4648-afa8-ceb13806a092", "type": "concept", "title": "Moral evil"}, {"id": "c8606ca2-7631-493a-8bf7-9236bf67fe01", "type": "concept", "title": "Horrendous evil and trauma"}], "description": "The course treats evil as more than an abstract puzzle."}, {"id": "e7db8fb0-a74e-4968-bab4-a1a6e75ba633", "type": "subtopic", "title": "Hiddenness", "children": [{"id": "0ac45e19-d8b1-45a8-9aae-45ae58e9f83c", "type": "concept", "title": "Nonresistant nonbelief"}, {"id": "33a77e4b-d9ef-422b-b49b-216b54cbf743", "type": "concept", "title": "Silence and ambiguity"}, {"id": "f157371a-2569-486a-8511-0915e21f9caa", "type": "concept", "title": "Faith under uncertainty"}], "description": "Students examine whether divine absence is evidence against theism."}]}, {"id": "1d9e4805-aada-4db0-b3b8-2346d79326f3", "type": "topic", "title": "Faith, Reason, Evidence, and Religious Epistemology", "description": "Explores whether religious belief can be rational, justified, basic, testimonial, or evidentially supported.", "children": [{"id": "0273122e-9df1-4bf4-96b4-ee27649079a3", "type": "subtopic", "title": "Evidentialism", "children": [{"id": "47478e65-6d7c-4276-bd83-7322c85336d3", "type": "concept", "title": "Clifford"}, {"id": "b204c5c5-ed96-4928-a62a-5857d925eee0", "type": "concept", "title": "Locke"}, {"id": "911dd462-7a9b-4b62-a9b8-9308dc4cf615", "type": "concept", "title": "Burden of proof"}], "description": "Students ask whether religious belief needs public evidence."}, {"id": "d34d7c7c-c2e4-41f7-a60a-3e777358e8e9", "type": "subtopic", "title": "Reformed and virtue epistemology", "children": [{"id": "a3336f2e-8a5a-45f8-9f20-aac8c5f29eb0", "type": "concept", "title": "Proper basicality"}, {"id": "ff3a3e50-60a9-4c01-ac0e-ebd44069f0b7", "type": "concept", "title": "Cognitive faculties"}, {"id": "7a75030c-9dc7-4a8d-b705-b67f812084ab", "type": "concept", "title": "Intellectual virtue"}], "description": "The course explores whether belief can be rational without argument."}, {"id": "7fb45ce6-bce9-4c8f-b268-4af26ea2c227", "type": "subtopic", "title": "Disagreement and testimony", "children": [{"id": "1c2870ff-1129-49f9-ba30-6f498f957b91", "type": "concept", "title": "Peer disagreement"}, {"id": "869dc70e-bdd8-4de9-8671-1326d52e0110", "type": "concept", "title": "Tradition and testimony"}, {"id": "addc7e7f-1277-45ce-b11c-d5d5eb88884b", "type": "concept", "title": "Epistemic humility"}], "description": "Students evaluate religious belief in communities of deep disagreement."}]}, {"id": "024ba567-4227-40ad-af08-2918ea23ee71", "type": "topic", "title": "Religious Experience, Mysticism, Testimony, and Revelation", "description": "Studies experience-based arguments, mystical claims, testimony, and revelation across traditions.", "children": [{"id": "93c762cb-29f5-4fc9-a37c-be09af35e98c", "type": "subtopic", "title": "Religious experience", "children": [{"id": "9f0f8cbf-adff-4457-bc70-5fe02a99d922", "type": "concept", "title": "Perceptual models"}, {"id": "d23c30ed-c48c-4c7d-aee1-1566525edd1f", "type": "concept", "title": "Mystical experience"}, {"id": "636e2666-ae48-46bd-aaa1-9015f186c5d1", "type": "concept", "title": "Cross-cultural variation"}], "description": "Students ask whether experiences can justify belief."}, {"id": "9eb26c26-9476-4147-9367-2a25fdbb3730", "type": "subtopic", "title": "Testimony", "children": [{"id": "f5d0f327-63fd-4505-a214-7a29cd2c2a4d", "type": "concept", "title": "Credibility"}, {"id": "18b84f19-1865-4a1e-9874-a022f0802040", "type": "concept", "title": "Defeaters"}, {"id": "b3f1c2b6-0b5f-4f1c-b3e5-6a31167c65c1", "type": "concept", "title": "Community formation"}], "description": "The topic studies how reports of experience become evidence for others."}, {"id": "f8533e20-e16b-47b5-8c36-6cd0c78924d2", "type": "subtopic", "title": "Revelation", "children": [{"id": "c9bb70c1-1801-41d8-8df0-9494c5bbd81a", "type": "concept", "title": "Scripture"}, {"id": "a2260151-c754-44e8-9b82-93fba0087c87", "type": "concept", "title": "Prophecy"}, {"id": "5c8f4458-60f5-4f93-b25e-43dcfd5ced9f", "type": "concept", "title": "Interpretation and authority"}], "description": "Students examine claims that ultimate reality communicates."}]}, {"id": "c798347c-c532-4af2-8e40-d70635431b09", "type": "topic", "title": "Miracles, Testimony, Probability, and Historical Claims", "description": "Focuses on miracle claims, Humean skepticism, testimonial evidence, and historical reasoning.", "children": [{"id": "b88edd46-c5f8-418f-9865-6858ba7e941c", "type": "subtopic", "title": "Hume on miracles", "children": [{"id": "9bf90fe6-10cc-4011-ae4b-218b57f177ca", "type": "concept", "title": "Uniform experience"}, {"id": "008f9090-5517-4929-abd6-06164559d638", "type": "concept", "title": "Wise proportioning"}, {"id": "5c9151f4-e1ce-4ebd-b2da-846823786e74", "type": "concept", "title": "Witness reliability"}], "description": "Students learn the classic skeptical challenge to miracle testimony."}, {"id": "7f7be444-9244-40fa-a8b7-307e718f32de", "type": "subtopic", "title": "Probability and evidence", "children": [{"id": "4aff260d-67d8-4e70-a44d-0c0fb9a8bf8f", "type": "concept", "title": "Prior probability"}, {"id": "3697caa4-3993-4c69-a612-ab80594c3df8", "type": "concept", "title": "Bayesian framing"}, {"id": "34d3a60e-6388-4375-a884-92c98eaa82f9", "type": "concept", "title": "Competing explanations"}], "description": "The course teaches careful reasoning about rare events."}, {"id": "70a7c405-c49c-4530-bf7b-2ccb14d91974", "type": "subtopic", "title": "Historical claims", "children": [{"id": "7237cc4f-ab6d-41a1-bdf4-68614497a359", "type": "concept", "title": "Documents and witnesses"}, {"id": "7fedb461-e5d7-452e-822d-f161aca81fb6", "type": "concept", "title": "Context and genre"}, {"id": "8f1b4692-afae-4f84-b245-a04a89024919", "type": "concept", "title": "Public versus private evidence"}], "description": "Students examine miracle claims as historical and philosophical arguments."}]}, {"id": "37a19ef4-cd85-4ab9-98e0-cfaadbbff604", "type": "topic", "title": "Religious Language, Analogy, Symbol, Verification, and Apophatic Speech", "description": "Asks how language about God or ultimate reality can be meaningful, literal, analogical, symbolic, or negative.", "children": [{"id": "a58aace5-b5b0-4f22-8408-1b4031fcb3f2", "type": "subtopic", "title": "Meaning and verification", "children": [{"id": "d2db3a03-9b77-4e7f-bb80-e8993703b0aa", "type": "concept", "title": "Logical positivism"}, {"id": "084e8dd0-34f6-48f2-b281-a4fc2d07cb27", "type": "concept", "title": "Falsification debate"}, {"id": "5e7955bb-2246-41c9-8d24-3d5940a42fbb", "type": "concept", "title": "Wittgensteinian approaches"}], "description": "Students study whether religious claims are cognitively meaningful."}, {"id": "554ad2b9-2bb1-4cdc-b8d7-74751456e21e", "type": "subtopic", "title": "Analogy and symbol", "children": [{"id": "0d67e503-d77c-4099-baaf-1aed84b1f317", "type": "concept", "title": "Univocal, equivocal, analogical speech"}, {"id": "a1195924-dd8b-44dc-8fa4-2f5df0db659e", "type": "concept", "title": "Metaphor and symbol"}, {"id": "77027c1d-7d0d-4b2b-a8eb-0dbe7e038eb0", "type": "concept", "title": "Myth and model"}], "description": "The topic asks how finite language can speak about the divine."}, {"id": "791d732b-9769-474c-9ce9-ac925e6e2509", "type": "subtopic", "title": "Negative theology", "children": [{"id": "78187895-85e2-489a-b024-653c5ab5438e", "type": "concept", "title": "Via negativa"}, {"id": "529fbba3-13a8-476c-825f-b5efa8b1fa24", "type": "concept", "title": "Ineffability"}, {"id": "562e8f9d-7385-48b2-ac9e-73f351dd15b9", "type": "concept", "title": "Religious practice and silence"}], "description": "Students explore apophatic traditions and their philosophical tensions."}]}, {"id": "6cc7dcf8-442f-469a-8c52-534156456143", "type": "topic", "title": "Religion and Science: Naturalism, Explanation, Mind, and Cosmology", "description": "Examines conflict, independence, integration, scientific explanation, consciousness, and naturalism.", "children": [{"id": "bf420a26-7b0d-436b-8f7b-f9f80214279a", "type": "subtopic", "title": "Models of relation", "children": [{"id": "c53007e4-1ae9-49a5-b880-110e4332da6a", "type": "concept", "title": "Methodological naturalism"}, {"id": "8cf27e59-a422-4b4a-bdcc-eea2e850458b", "type": "concept", "title": "Non-overlapping domains"}, {"id": "4a596ec1-12bc-4ed5-84a8-c9b9c7efe99c", "type": "concept", "title": "Explanatory pluralism"}], "description": "Students compare conflict, independence, dialogue, and integration models."}, {"id": "ea1b71da-4d39-4d01-9b00-5841745b8ea8", "type": "subtopic", "title": "Mind and consciousness", "children": [{"id": "393bb57c-a238-47c3-b513-e48e0dd7bae0", "type": "concept", "title": "Emergence"}, {"id": "071fc84a-8e88-47af-8905-3bec29287bf0", "type": "concept", "title": "Consciousness"}, {"id": "d97dc760-f2f7-42db-ba72-83e5a6172a21", "type": "concept", "title": "Soul and embodiment"}], "description": "The topic connects religion to hard questions about mind and personhood."}, {"id": "b666a974-791c-460e-a678-d0a4b3764a14", "type": "subtopic", "title": "Cosmology and explanation", "children": [{"id": "da0dad3d-692a-48d8-aa05-88b8c814c5f3", "type": "concept", "title": "Origins"}, {"id": "0083b5f2-9da2-4ded-84af-a4b2fc4b53ef", "type": "concept", "title": "Laws of nature"}, {"id": "a230bae4-f41b-45e6-86ec-eb143850fe36", "type": "concept", "title": "Why is there something rather than nothing"}], "description": "Students ask what science explains and what philosophical questions remain."}]}, {"id": "687b8da0-1dbf-4fa3-993a-72872691bac1", "type": "topic", "title": "Religious Pluralism, Exclusivism, Inclusivism, and Diversity", "description": "Studies philosophical responses to many religions, disagreement, salvation, truth, and epistemic humility.", "children": [{"id": "e3c18db7-6697-456a-b748-be549cea4242", "type": "subtopic", "title": "Models of diversity", "children": [{"id": "db5d33dc-dca3-4e40-9c18-bbb267316740", "type": "concept", "title": "Exclusivism"}, {"id": "27d54567-1706-4869-95db-00f595824713", "type": "concept", "title": "Inclusivism"}, {"id": "b8a61583-15f8-4400-b6bd-ec88b9cf8361", "type": "concept", "title": "Pluralism"}], "description": "Students learn major philosophical responses to many religions."}, {"id": "ae3784ca-1abe-4cb7-b40a-79d1353aa00b", "type": "subtopic", "title": "Truth and salvation", "children": [{"id": "eca9c5b5-1471-4d85-95e3-79392780a04b", "type": "concept", "title": "Contradictory doctrines"}, {"id": "0748f3f8-66c2-4008-b0d1-61bce2eb8226", "type": "concept", "title": "Ultimate reality and appearances"}, {"id": "a50720f4-8ec3-42f5-a089-dc075d4e288b", "type": "concept", "title": "Soteriological pluralism"}], "description": "The course asks whether conflicting claims can all be true or salvific."}, {"id": "2cba7339-136b-4fb7-8dda-733576332964", "type": "subtopic", "title": "Disagreement ethics", "children": [{"id": "9dbcb7e1-cfcd-4434-81b7-75fc30551f19", "type": "concept", "title": "Respect and critique"}, {"id": "c5b32ae0-79e1-4dd1-97bd-d355f2eec677", "type": "concept", "title": "Epistemic peerhood"}, {"id": "ea2f1d84-c676-4c07-8f2f-678d5f6493ce", "type": "concept", "title": "Power and representation"}], "description": "Students practice intellectual humility in religious disagreement."}]}, {"id": "e8b268c0-c334-45af-be45-33fdb29e0de1", "type": "topic", "title": "Atheism, Agnosticism, Skepticism, and Secular Critique", "description": "Takes nonreligious worldviews seriously as philosophical positions with their own arguments and burdens.", "children": [{"id": "5e7f0bde-78ff-4829-9d45-4cb3e5295771", "type": "subtopic", "title": "Atheism and agnost